pragma solidity ^0.8.20;
contract MemorySort {
    function firstGreater(uint256[] calldata values, uint256 threshold) external pure returns (uint256) {
        for (uint256 i = 0; i < values.length; i++) {
            if (values[i] > threshold) return values[i];
        }
        return 0;
    }
}
